css:
#tongsci2-2-1-1-1-cover .frame { flex-direction: row; gap: 72px; }
#tongsci2-2-1-1-1-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci2-2-1-1-1-cover h1 { font-size: 112px; }
#tongsci2-2-1-1-1-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci2-2-1-1-1-cover .footer { left: 1100px; right: 300px; }
#tongsci2-2-1-1-1-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci2-2-1-1-1-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci2-2-1-1-1-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci2-2-1-1-1-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci2-2-1-1-1-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci2-2-1-1-1-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci2-2-1-1-1-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci2-2-1-1-1-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci2-2-1-1-1-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci2-2-1-1-1-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci2-2-1-1-1-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci2-2-1-1-1-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }

js:
/* tongsci2.2-1-1.1.cover */
(function () {
  'use strict';
  const { part } = window.Deck;
  const L1 = window.L1;
  const single = (btns) => btns.forEach((b) => b.addEventListener('click', () => {
    const on = b.getAttribute('aria-pressed') !== 'true';
    btns.forEach((x) => x.setAttribute('aria-pressed', String(on && x === b)));
  }));
  // 체험 장 해 볼 일: 지금 단계 번호(0 = 끝)
  const mark = (root, n, max = 3) => { const ok = []; for (let k = 1; k <= max; k++) if (n === 0 || k < n) ok.push(k); L1.steps(root, n, ok); L1.done(root, n === 0); };
  window.EcoMark = mark;
  // 1. 표지: 두 밭 타임랩스 + 예측(답은 확인 장의 «사건 파일 1 풀기»에서)
  part('tongsci2-2-1-1-1-cover', (root) => {
    const w = window.WormBed.mount(root);
    single([...root.querySelectorAll('.share-opts button')]);
    return { setActive: w.setActive };
  });

  // 2. 이론: 개체에서 생태계까지 — 사진을 누르면 맞는 왼쪽 상자가 밝아진다
})();
